"""Semantic version parsing, comparison, and range matching.

Versions follow Semantic Versioning 2.0.0: ``MAJOR.MINOR.PATCH``, then an
optional pre-release (``-`` followed by dot-separated identifiers) and an
optional build (``+`` followed by dot-separated identifiers). Identifiers
are non-empty and made of ASCII letters, digits, and hyphens. Numeric parts
(MAJOR, MINOR, PATCH, and all-digit pre-release identifiers) must not have
leading zeros. Anything else is invalid and raises ``ValueError``.

Precedence (``compare``) follows the SemVer 2.0.0 rules: compare MAJOR,
MINOR, and PATCH numerically; a version with a pre-release is lower than
the same version without one; pre-release identifiers are compared left to
right, all-digit ones numerically and the rest in ASCII order, with
all-digit identifiers lower than the rest, and a shorter list lower when
all its identifiers equal the start of a longer one. Build metadata is
ignored.

Ranges (``satisfies``) are one or more comparator sets joined by ``||``; a
version satisfies the range if it satisfies any set. A set is one or more
comparators separated by whitespace, all of which must hold. A comparator
is a full version optionally prefixed by an operator:

- ``=`` (or no operator), ``>``, ``>=``, ``<``, ``<=``: by precedence.
- ``^X.Y.Z``: at least ``X.Y.Z`` and below the next version that changes
  the leftmost non-zero part, i.e. ``^1.2.3`` is ``>=1.2.3 <2.0.0``,
  ``^0.2.3`` is ``>=0.2.3 <0.3.0``, and ``^0.0.3`` is ``>=0.0.3 <0.0.4``.
- ``~X.Y.Z``: at least ``X.Y.Z`` and below ``X.(Y+1).0``.

A version with a pre-release satisfies a set only if some comparator in
that set has a pre-release on the same MAJOR.MINOR.PATCH (so
``1.2.3-beta.2`` satisfies ``>=1.2.3-beta.1`` but not ``>=1.0.0``).
Invalid ranges raise ``ValueError``.
"""

from __future__ import annotations

import re
from dataclasses import dataclass

_IDENTIFIER = r"[0-9A-Za-z-]+"
_VERSION_RE = re.compile(
    r"^(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)\.(0|[1-9][0-9]*)"
    r"(?:-(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?"
    r"(?:\+(" + _IDENTIFIER + r"(?:\." + _IDENTIFIER + r")*))?$"
)
_COMPARATOR_RE = re.compile(r"^(<=|>=|<|>|=|\^|~)?(.*)$")
_OPERATORS = ("=", ">", ">=", "<", "<=", "^", "~")


@dataclass(frozen=True)
class Version:
    major: int
    minor: int
    patch: int
    prerelease: tuple[str, ...] = ()
    build: tuple[str, ...] = ()

    def __str__(self) -> str:
        """The version in canonical form, e.g. ``1.2.3-rc.1+build.5``."""
        text = f"{self.major}.{self.minor}.{self.patch}"
        if self.prerelease:
            text += "-" + ".".join(self.prerelease)
        if self.build:
            text += "+" + ".".join(self.build)
        return text


def parse(text: str) -> Version:
    """Parse a version string."""
    match = _VERSION_RE.match(text)
    if match is None:
        raise ValueError(f"invalid version: {text!r}")

    major, minor, patch, prerelease, build = match.groups()
    prerelease_parts = tuple(prerelease.split(".")) if prerelease else ()
    for identifier in prerelease_parts:
        if identifier.isdigit() and len(identifier) > 1 and identifier[0] == "0":
            raise ValueError(f"invalid version: {text!r}")
    build_parts = tuple(build.split(".")) if build else ()

    return Version(
        int(major),
        int(minor),
        int(patch),
        prerelease_parts,
        build_parts,
    )


def _coerce(version: str | Version) -> Version:
    return version if isinstance(version, Version) else parse(version)


def compare(a: str | Version, b: str | Version) -> int:
    """Return -1, 0, or 1 as ``a`` has lower, equal, or higher precedence."""
    left = _coerce(a)
    right = _coerce(b)

    for x, y in (
        (left.major, right.major),
        (left.minor, right.minor),
        (left.patch, right.patch),
    ):
        if x != y:
            return -1 if x < y else 1

    left_pre = left.prerelease
    right_pre = right.prerelease
    if not left_pre and not right_pre:
        return 0
    if not left_pre:
        return 1
    if not right_pre:
        return -1

    for x, y in zip(left_pre, right_pre):
        if x == y:
            continue
        x_numeric = x.isdigit()
        y_numeric = y.isdigit()
        if x_numeric and y_numeric:
            x_value = int(x)
            y_value = int(y)
            if x_value != y_value:
                return -1 if x_value < y_value else 1
        elif x_numeric:
            return -1
        elif y_numeric:
            return 1
        else:
            return -1 if x < y else 1

    if len(left_pre) == len(right_pre):
        return 0
    return -1 if len(left_pre) < len(right_pre) else 1


def _parse_comparators(text: str) -> list[tuple[str, Version]]:
    if not text.strip():
        raise ValueError(f"invalid range: {text!r}")

    tokens = text.split()
    comparators: list[tuple[str, Version]] = []
    index = 0
    while index < len(tokens):
        token = tokens[index]
        if token in _OPERATORS:
            if index + 1 >= len(tokens):
                raise ValueError(f"invalid range: {text!r}")
            token += tokens[index + 1]
            index += 2
        else:
            index += 1

        match = _COMPARATOR_RE.match(token)
        if match is None:
            raise ValueError(f"invalid range: {text!r}")
        operator = match.group(1) or "="
        comparators.append((operator, parse(match.group(2))))

    if not comparators:
        raise ValueError(f"invalid range: {text!r}")
    return comparators


def _comparator_holds(
    version: Version, operator: str, bound: Version
) -> bool:
    if operator in ("=", ">", ">=", "<", "<="):
        result = compare(version, bound)
        return {
            "=": result == 0,
            ">": result > 0,
            ">=": result >= 0,
            "<": result < 0,
            "<=": result <= 0,
        }[operator]

    if operator == "^":
        if compare(version, bound) < 0:
            return False
        if bound.major > 0:
            upper = Version(bound.major + 1, 0, 0)
        elif bound.minor > 0:
            upper = Version(0, bound.minor + 1, 0)
        else:
            upper = Version(0, 0, bound.patch + 1)
        return compare(version, upper) < 0

    if operator == "~":
        if compare(version, bound) < 0:
            return False
        upper = Version(bound.major, bound.minor + 1, 0)
        return compare(version, upper) < 0

    raise ValueError(f"invalid operator: {operator!r}")


def _set_holds(version: Version, comparators: list[tuple[str, Version]]) -> bool:
    if not all(
        _comparator_holds(version, operator, bound)
        for operator, bound in comparators
    ):
        return False

    if version.prerelease:
        for _, bound in comparators:
            if bound.prerelease and (
                bound.major,
                bound.minor,
                bound.patch,
            ) == (version.major, version.minor, version.patch):
                return True
        return False

    return True


def satisfies(version: str | Version, range_: str) -> bool:
    """Whether ``version`` is in ``range_``."""
    parsed = _coerce(version)
    sets = [
        _parse_comparators(part) for part in range_.split("||")
    ]
    return any(_set_holds(parsed, comparators) for comparators in sets)

"""Write and read Markdown (GitHub-flavored) pipe tables.

``format_table`` writes a header line, a delimiter line, and one line per
row, separated by ``\\n`` with no trailing newline. Every line is ``| ``,
then the column cells joined by `` | ``, then `` |``.

Cell text is ``str(value)``, or empty for ``None``, with each ``|``
escaped as ``\\|``. A row shorter than the header is padded with empty
cells; a longer one raises ``ValueError``. Each column is as wide as its
longest cell text (after escaping, and including the header), and at
least 3.

Cells are padded with spaces to the column width according to the
column's alignment: ``"left"`` or ``None`` pads on the right, ``"right"``
pads on the left, and ``"center"`` pads both sides equally, with any odd
space on the right. ``align`` gives one alignment per column (default all
``None``); any other value, or a list of the wrong length, raises
``ValueError``.

Delimiter cells are dashes filling the column width, with a colon replacing
the first dash for ``"left"``, the last for ``"right"``, and both for
``"center"`` (``:--``, ``--:``, ``:-:`` at width 3).

``parse_table`` reads such a table back, tolerating any padding and missing
leading or trailing pipes: it returns the header and the rows as lists of
stripped strings with ``\\|`` unescaped, and the alignment of each column
from the delimiter line (``None`` for plain dashes). Each delimiter cell
must be one or more dashes with an optional colon at either end. Text that
isn't a table (fewer than two lines, a bad delimiter line, or a delimiter
line or row with a different number of cells than the header) raises
``ValueError``.
"""

from __future__ import annotations

import re

_ALIGNMENTS = (None, "left", "right", "center")
_DELIMITER_RE = re.compile(r"^(:?)(-+)(:?)$")


def _cell_text(value: object) -> str:
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    extra = width - len(text)
    if extra <= 0:
        return text
    if align == "right":
        return " " * extra + text
    if align == "center":
        left = extra // 2
        return " " * left + text + " " * (extra - left)
    return text + " " * extra


def _delimiter(width: int, align: str | None) -> str:
    if align == "left":
        return ":" + "-" * (width - 1)
    if align == "right":
        return "-" * (width - 1) + ":"
    if align == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _line(cells: list[str]) -> str:
    return "| " + " | ".join(cells) + " |"


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    header_cells = [_cell_text(value) for value in header]
    column_count = len(header_cells)

    if align is None:
        alignments: list[str | None] = [None] * column_count
    else:
        alignments = list(align)
        if len(alignments) != column_count:
            raise ValueError("align must have one entry per column")
        for alignment in alignments:
            if alignment not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {alignment!r}")

    body: list[list[str]] = []
    for row in rows:
        cells = [_cell_text(value) for value in row]
        if len(cells) > column_count:
            raise ValueError("row has more cells than the header")
        cells.extend([""] * (column_count - len(cells)))
        body.append(cells)

    widths: list[int] = []
    for index in range(column_count):
        width = len(header_cells[index])
        for cells in body:
            width = max(width, len(cells[index]))
        widths.append(max(3, width))

    lines = [
        _line(
            [
                _pad(header_cells[index], widths[index], alignments[index])
                for index in range(column_count)
            ]
        ),
        _line(
            [
                _delimiter(widths[index], alignments[index])
                for index in range(column_count)
            ]
        ),
    ]
    for cells in body:
        lines.append(
            _line(
                [
                    _pad(cells[index], widths[index], alignments[index])
                    for index in range(column_count)
                ]
            )
        )

    return "\n".join(lines)


def _split_line(line: str) -> list[str]:
    text = line.strip()
    cells: list[str] = []
    buffer: list[str] = []
    index = 0

    while index < len(text):
        character = text[index]
        if character == "\\" and index + 1 < len(text) and text[index + 1] == "|":
            buffer.append("\\|")
            index += 2
        elif character == "|":
            cells.append("".join(buffer))
            buffer = []
            index += 1
        else:
            buffer.append(character)
            index += 1
    cells.append("".join(buffer))

    if cells and not cells[0].strip() and text.startswith("|"):
        cells.pop(0)
    if cells and not cells[-1].strip() and text.endswith("|"):
        cells.pop()

    return [cell.strip().replace("\\|", "|") for cell in cells]


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    if len(lines) < 2:
        raise ValueError("not a table")

    header = _split_line(lines[0])
    delimiter_cells = _split_line(lines[1])
    if len(delimiter_cells) != len(header):
        raise ValueError("delimiter line has the wrong number of cells")

    alignments: list[str | None] = []
    for cell in delimiter_cells:
        match = _DELIMITER_RE.match(cell)
        if match is None:
            raise ValueError(f"invalid delimiter cell: {cell!r}")
        has_left = bool(match.group(1))
        has_right = bool(match.group(3))
        if has_left and has_right:
            alignments.append("center")
        elif has_left:
            alignments.append("left")
        elif has_right:
            alignments.append("right")
        else:
            alignments.append(None)

    rows: list[list[str]] = []
    for line in lines[2:]:
        cells = _split_line(line)
        if len(cells) != len(header):
            raise ValueError("row has the wrong number of cells")
        rows.append(cells)

    return header, rows, alignments
